C353_R = [('    if (!t || B.t > 4) { chBombBoom(z); return; }\n    const dx = t.foot.x - z.foot.x, dz = t.foot.z - z.foot.z, d = Math.hypot(dx, dz) || 1e-6, v = z.speed * POUNCE;\n    if (d - (z.r || BODY) - (t.r || BODY) <= 0.15 + v * dt) { chBombBoom(z); return; }\n    z.vel.set(dx / d * v, dz / d * v);', '    if (!t || B.t > 6) { chBombBoom(z); return; }\n    const dx = t.foot.x - z.foot.x, dz = t.foot.z - z.foot.z, d = Math.hypot(dx, dz) || 1e-6;   // c353: 평소처럼 달려가다가 덮치는 거리(ATTACK) 안에 들면 덮친다 — 덮쳐서 닿으면 감염 대신 터진다\n    if (!B.pounce && d <= ATTACK && !chPounceBlocked(z.foot.x, z.foot.z, t.foot.x, t.foot.z)) B.pounce = true;\n    const v = B.pounce ? z.speed * POUNCE : z.speed;\n    if (d - (z.r || BODY) - (t.r || BODY) <= 0.15 + v * dt) { chBombBoom(z); return; }\n    if (B.pounce) z.vel.set(dx / d * v, dz / d * v); else steer(z.vel, wantV.set(dx / d * v, dz / d * v), ACCEL * dt);'), ("        if (a.mode === 'pounce' || b.mode === 'pounce') continue;   // 덮치는 동안은 아무 몸이나 통과", "        if (a.mode === 'pounce' || b.mode === 'pounce' || (a.bombing && a.bombing.pounce) || (b.bombing && b.bombing.pounce)) continue;   // 덮치는 동안은 아무 몸이나 통과 (c353: 자폭 덮치기도)")]
